package net.officefloor.hq.app.person;

/** A SNAPSHOT written for a person: the day being left (yyyy-MM-dd) and their due-total on it (or n/a). */
public record Snapshot(String day, String dueTotal) {
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** Before a new today takes effect: one SNAPSHOT line per person, in list order, with the
 *  due-total as it stood on the day being left, kept on the person too; nothing when the today does not change. */
public class RecordSnapshots {
    public void record(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "by", required = false) String by, @Val LocalDate today,
            @Val Rollup before, SheetRepository sheets, PersonRepository people,
            Audit audit) {
        String id = sheetId.trim();
        LocalDate leaving = sheets.today(id);
        if (today.equals(leaving)) return;
        String head = "SNAPSHOT sheet=" + id + " by=" + (by == null ? "" : by);
        before.people().forEach((personId, figures) -> {
            String due = figures.dueTotal() == null ? "n/a" : figures.dueTotal();
            people.addSnapshot(id, personId, leaving, due);
            audit.record(head + " name=" + figures.name() + " due-total=" + due);
        });
    }
}
-- Each SNAPSHOT written for a person, in the order written: the day being left (the sheet's today
-- before it changed) and their due-total on it (text: two decimals, or n/a).
CREATE TABLE person_snapshot (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL,
    day_left  DATE         NOT NULL,
    due_total VARCHAR(30)  NOT NULL
);
CREATE INDEX person_snapshot_person ON person_snapshot (sheet_id, person_id, id);
# POST /api/sheets/{sheetId}/today — change the sheet's today (the date everything on it goes by).
# Before the change takes effect, a SNAPSHOT line per person with the due-total on the day being left.
# With grace days set, the open periods past them are closed (auto=yes) before the rollup lines.
# A viewer may change nothing: refused before anything is read or written.
guard:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: validate
validate:
  class: net.officefloor.hq.app.sheet.ValidateSheetToday
  next: before
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: snapshot
snapshot:
  class: net.officefloor.hq.app.sheet.RecordSnapshots
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.sheet.ApplySheetToday
  govern: [ transaction ]
  next: autoclose
autoclose:
  class: net.officefloor.hq.app.period.AutoClosePeriods
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.sheet.RespondWithSheet
